 * Parsing of the build graph text format into a task/dependency graph.
 */

export class CliError extends Error {
  constructor(message, code = 2) {
    super(message)
    this.code = code
  }
}

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses the input text into a graph of tasks and dependencies.
 *
 * Returns `{ tasks, deps }` where `tasks` maps a task name to its cost and
 * `deps` maps a task name to the deduplicated list of names it depends on,
 * in first-seen order. Throws a `CliError` for any malformed line or an
 * unknown task reference.
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const deps = new Map()
  const references = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`error: line ${lineNo}: expected task <name> <cost>`)
      }
      const name = words[1]
      const costStr = words[2]
      if (!NAME_RE.test(name)) {
        throw new CliError(`error: line ${lineNo}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(`error: line ${lineNo}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new CliError(`error: line ${lineNo}: task ${name} is declared twice`)
      }
      tasks.set(name, parseInt(costStr, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`error: line ${lineNo}: expected dep <name> <dependency>...`)
      }
      const name = words[1]
      const depNames = words.slice(2)
      for (const n of [name, ...depNames]) {
        if (!NAME_RE.test(n)) {
          throw new CliError(`error: line ${lineNo}: invalid task name ${n}`)
        }
      }
      references.push(name)
      for (const d of depNames) references.push(d)
      if (!deps.has(name)) deps.set(name, [])
      const list = deps.get(name)
      for (const d of depNames) {
        if (!list.includes(d)) list.push(d)
      }
    } else {
      throw new CliError(`error: line ${lineNo}: unknown directive ${directive}`)
    }
  }

  for (const name of references) {
    if (!tasks.has(name)) {
      throw new CliError(`error: unknown task ${name}`)
    }
  }

  return { tasks, deps }
}
"}

