{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-D2sX5z/src/graph.js","content":"/**
 * Graph analysis over a parsed build graph: cycle detection, the
 * unlimited-worker schedule (waves, start/finish/depth), task priority, and
 * the fixed-worker-count pack simulation.
 */

/**
 * Finds a cycle, if any, by depth-first search starting from each task in
 * ascending name order and walking each task's dependencies in ascending
 * name order. Returns the cycle as an array of names from the re-entered
 * task through the search stack back to a repeat of that name, or `null`
 * when the graph is acyclic.
 */
export function findCycle(tasks, deps) {
  const names = [...tasks.keys()].sort()
  const state = new Map()
  const stack = []

  function visit(name) {
    state.set(name, 'active')
    stack.push(name)
    const children = [...(deps.get(name) || [])].sort()
    for (const child of children) {
      const childState = state.get(child)
      if (childState === 'active') {
        const idx = stack.indexOf(child)
        const cycle = stack.slice(idx)
        cycle.push(child)
        return cycle
      }
      if (childState !== 'done') {
        const found = visit(child)
        if (found) return found
      }
    }
    stack.pop()
    state.set(name, 'done')
    return null
  }

  for (const name of names) {
    if (!state.has(name)) {
      const found = visit(name)
      if (found) return found
    }
  }
  return null
}

/**
 * Computes, for every task, its start time, finish time and wave depth
 * under unlimited workers. A task starts when the last of its dependencies
 * finishes (or at 0 with none) and its depth is one past the deepest
 * dependency's depth (or 0 with none). Assumes the graph has no cycle.
 */
export function computeSchedule(tasks, deps) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  function compute(name) {
    if (finish.has(name)) return
    const children = deps.get(name) || []
    let maxFinish = 0
    let maxDepth = -1
    for (const child of children) {
      compute(child)
      if (finish.get(child) > maxFinish) maxFinish = finish.get(child)
      if (depth.get(child) > maxDepth) maxDepth = depth.get(child)
    }
    const cost = tasks.get(name)
    start.set(name, maxFinish)
    finish.set(name, maxFinish + cost)
    depth.set(name, children.length === 0 ? 0 : maxDepth + 1)
  }

  for (const name of tasks.keys()) compute(name)

  return { start, finish, depth }
}

/**
 * Computes, for every task, the cost of the longest chain that begins at
 * it: its own cost plus the costs down to whichever task that depends on
 * it (directly or transitively) has none depending on it in turn. Assumes
 * the graph has no cycle.
 */
export function computePriority(tasks, deps) {
  const successors = new Map()
  for (const name of tasks.keys()) successors.set(name, [])
  for (const [name, children] of deps) {
    for (const child of children) {
      successors.get(child)?.push(name)
    }
  }

  const priority = new Map()

  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    let maxSuccessor = 0
    for (const successor of successors.get(name) || []) {
      const p = compute(successor)
      if (p > maxSuccessor) maxSuccessor = p
    }
    const value = tasks.get(name) + maxSuccessor
    priority.set(name, value)
    return value
  }

  for (const name of tasks.keys()) compute(name)

  return priority
}

/**
 * Simulates the graph on `workerCount` workers, greedily starting the
 * highest-priority ready task (ties broken by ascending name) on the
 * lowest-index free worker whenever both are available, and otherwise
 * advancing time to the next worker completion. Returns each worker's
 * ordered run log and the overall makespan.
 */
export function pack(tasks, deps, workerCount) {
  const priority = computePriority(tasks, deps)
  const finishTime = new Map()
  const pending = new Set(tasks.keys())
  const workers = Array.from({ length: workerCount }, () => ({ busyUntil: 0, log: [] }))

  let time = 0
  while (pending.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false

      let workerIndex = -1
      for (let i = 0; i < workers.length; i++) {
        if (workers[i].busyUntil <= time) {
          workerIndex = i
          break
        }
      }
      if (workerIndex === -1) break

      let best = null
      for (const name of pending) {
        const ready = (deps.get(name) || []).every((d) => finishTime.get(d) <= time)
        if (!ready) continue
        if (best === null) {
          best = name
          continue
        }
        const pBest = priority.get(best)
        const pName = priority.get(name)
        if (pName > pBest || (pName === pBest && name < best)) best = name
      }
      if (best === null) break

      const cost = tasks.get(best)
      const finish = time + cost
      workers[workerIndex].log.push({ name: best, start: time, finish })
      workers[workerIndex].busyUntil = finish
      finishTime.set(best, finish)
      pending.delete(best)
      progressed = true
    }

    if (pending.size === 0) break

    let next = Infinity
    for (const w of workers) {
      if (w.busyUntil > time && w.busyUntil < next) next = w.busyUntil
    }
    if (next === Infinity) break
    time = next
  }

  let makespan = 0
  for (const w of workers) {
    for (const entry of w.log) {
      if (entry.finish > makespan) makespan = entry.finish
    }
  }

  return { workers, makespan }
}
"}

