/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import fs from 'node:fs'
import { CliError, parseGraph } from './parse.js'
import { computePriority, computeSchedule, findCycle, pack } from './graph.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'

function fail(message, code = 2) {
  process.stderr.write(`${message}\n`)
  process.exit(code)
}

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(argv[1])) {
      fail('error: workers must be a positive integer')
    }
    return { mode: 'pack', workerCount: parseInt(argv[1], 10) }
  }
  fail(USAGE)
  return null
}

function main() {
  const { mode, workerCount } = parseArgs(process.argv.slice(2))
  const input = fs.readFileSync(0, 'utf8')

  let tasks
  let deps
  try {
    ;({ tasks, deps } = parseGraph(input))
  } catch (err) {
    if (err instanceof CliError) fail(err.message, err.code)
    throw err
  }

  const cycle = findCycle(tasks, deps)
  if (cycle) {
    fail(`error: cycle: ${cycle.join(' -> ')}`, 3)
  }

  if (mode === 'waves') {
    printWaves(tasks, deps)
  } else if (mode === 'explain') {
    printExplain(tasks, deps)
  } else {
    printPack(tasks, deps, workerCount)
  }
}

function printWaves(tasks, deps) {
  const { finish, depth } = computeSchedule(tasks, deps)
  const names = [...tasks.keys()]

  let maxDepth = -1
  let total = 0
  for (const name of names) {
    if (depth.get(name) > maxDepth) maxDepth = depth.get(name)
    if (finish.get(name) > total) total = finish.get(name)
  }

  const lines = []
  for (let k = 0; k <= maxDepth; k++) {
    const wave = names.filter((name) => depth.get(name) === k).sort()
    lines.push(`wave ${k}: ${wave.join(' ')}`)
  }
  lines.push(`total ${total}`)
  process.stdout.write(lines.map((line) => `${line}\n`).join(''))
}

function printExplain(tasks, deps) {
  const { start, finish, depth } = computeSchedule(tasks, deps)
  const names = [...tasks.keys()].sort()

  let total = 0
  for (const name of names) {
    if (finish.get(name) > total) total = finish.get(name)
  }

  const lines = names.map(
    (name) => `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`,
  )
  lines.push(`total ${total}`)
  process.stdout.write(lines.map((line) => `${line}\n`).join(''))
}

function printPack(tasks, deps, workerCount) {
  const { workers, makespan } = pack(tasks, deps, workerCount)

  const lines = workers.map((worker, i) => {
    const entries = worker.log.map((e) => ` ${e.name}@${e.start}-${e.finish}`).join('')
    return `worker ${i}:${entries}`
  })
  lines.push(`makespan ${makespan}`)
  process.stdout.write(lines.map((line) => `${line}\n`).join(''))
}

main()
"}

